create function pg_temp.bundle() returns jsonb language sql as $$select jsonb_set(jsonb_set(jsonb_set(pg_temp.base_bundle(),'{questions,3,student,kind}','"open_ended"'),'{questions,3,student,choices}','[]'),'{questions,3,teacher,correct_key}','null');$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
insert into state(id) select (public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())->>'id')::uuid;
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-1',1,0,'suitable','Synthetic test only');
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-2',1,0,'suitable','Synthetic test only');
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-3',1,0,'suitable','Synthetic test only');
select public.admin_review_library_question(gen_random_uuid(),(select id from state),'question-4',1,0,'suitable','Synthetic test only');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000004301',(select id from state),jsonb_build_array(jsonb_build_object('source_hash',pg_temp.bundle()#>>'{assets,0,sha256}','base64',pg_temp.bundle()#>>'{assets,0,base64}')));
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
select public.admin_set_library_publication(gen_random_uuid(),(select id from state),0,public.admin_library_publication((select id from state))#>>'{checks,review_fingerprint}','Test geometry','Test',array['free']::public.plan_code[],'Test curriculum',true,'published');


create function pg_temp.make_group() returns uuid language sql as $$select public.admin_create_reviewed_group_exam('60000000-0000-4000-8000-000000005901',(select id from state),1,'Reviewed cohort',array['source:segments','question:question-4'],now()-interval '1 hour',now()+interval '1 hour',20,array['free']::public.plan_code[],true);$$;
select pg_temp.make_group();
reset role;
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000004702','10000000-0000-4000-8000-000000004302','Child',5);
update public.plans set cohort_monthly=5,prova_monthly_exams=null where code='free';
update public.app_settings set value='true' where key in('cohorts.enabled','sources.enabled','question_groups.enabled');
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000004304','second-parent@test.invalid');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000004302','00000000-0000-4000-8000-000000004304');
insert into auth.sessions(id,user_id) select gen_random_uuid(),id from auth.users where id in('00000000-0000-4000-8000-000000004302','00000000-0000-4000-8000-000000004303','00000000-0000-4000-8000-000000004304');
insert into public.push_tokens(user_id,family_id,role,platform,token,token_type) values
 ('00000000-0000-4000-8000-000000004302','10000000-0000-4000-8000-000000004302','parent','ios','qa-parent-one','apns'),
 ('00000000-0000-4000-8000-000000004304','10000000-0000-4000-8000-000000004302','parent','android','qa-parent-two','fcm'),
 ('00000000-0000-4000-8000-000000004303','10000000-0000-4000-8000-000000004303','parent','ios','qa-foreign-parent','apns');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004302","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004302"}}',true);
select set_config('test.exam',public.enroll_reviewed_group_exam('60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',false,true,true)::text,true);
select set_config('test.attempt',(public.start_exam_attempt(current_setting('test.exam')::uuid)).id::text,true);
select public.finish_exam_attempt(current_setting('test.attempt')::uuid);
reset role;
select set_config('test.entry',(select id::text from public.group_exam_entries where exam_id=current_setting('test.exam')::uuid),true);
update public.group_exams set ends_at=now()-interval '1 minute';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
create function pg_temp.detail() returns jsonb language sql as $$select public.admin_cohort_review_detail(current_setting('test.entry')::uuid)$$;
create function pg_temp.review(req uuid default gen_random_uuid(),rev int default 0,pts jsonb default '{"c1":1,"c2":1,"c3":0,"c4":0}',outcome text default 'scored',ap int default null,response text default null) returns jsonb language sql as $$select public.admin_save_cohort_review(req,current_setting('test.entry')::uuid,4,rev,pg_temp.detail()#>>'{questions,3,answer_hash}',pts,outcome,'Two criteria evidenced in the answer.',ap,response)$$;
create function pg_temp.publish(req uuid default gen_random_uuid(),fingerprint text default null,version int default null) returns jsonb language sql as $$select public.admin_publish_cohort_results(req,'60000000-0000-4000-8000-000000005901',coalesce(fingerprint,public.admin_cohort_review_queue('60000000-0000-4000-8000-000000005901')#>>'{state,fingerprint}'),coalesce(version,(public.admin_cohort_review_queue('60000000-0000-4000-8000-000000005901')#>>'{state,version}')::int))$$;
select pg_temp.review(pts=>'{"c1":0,"c2":0,"c3":0,"c4":0}',outcome=>'not_answered');
reset role;
select is((select count(*)::int from public.push_outbox where kind='cohort_results'),0,'review without publication does not notify');
set local role authenticated;
select pg_temp.publish('80000000-0000-4000-8000-000000006001');
select pg_temp.publish('80000000-0000-4000-8000-000000006001',version=>0);
reset role;
select set_config('test.outbox',(select id::text from public.push_outbox where kind='cohort_results'),true);
select is((select count(*)::int from public.push_outbox where kind='cohort_results'),1,'publication replay produces only one family notification');
select is((select payload from public.push_outbox where id=current_setting('test.outbox')::bigint),'{"group_id":"60000000-0000-4000-8000-000000005901","publication_version":1}'::jsonb,'payload contains no child name score or answer');
select is((select exclude_user_id from public.push_outbox where id=current_setting('test.outbox')::bigint),null::uuid,'publication actor is not excluded from parent audience');
select is((select count(*)::int from public.push_targets(current_setting('test.outbox')::bigint)),2,'both live parents targeted; other family excluded');
insert into public.push_preferences(user_id,family_id,exams) values('00000000-0000-4000-8000-000000004302','10000000-0000-4000-8000-000000004302',false);
select is((select count(*)::int from public.push_targets(current_setting('test.outbox')::bigint)),1,'exam preference suppresses cohort notification');
update public.push_preferences set exams=true;
savepoint logged_out;
delete from auth.sessions where user_id='00000000-0000-4000-8000-000000004302';
select is((select count(*)::int from public.push_targets(current_setting('test.outbox')::bigint)),1,'logged-out parent not targeted');
rollback to logged_out;
savepoint cancelled;
update public.group_exams set status='cancelled';
select is((select count(*)::int from public.push_targets(current_setting('test.outbox')::bigint)),0,'cancelled cohort suppresses queued result message');
rollback to cancelled;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004302","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004302"}}',true);
select throws_ok($$select public.push_targets(current_setting('test.outbox')::bigint)$$,'42501',null,'parent cannot read notification token destinations');
select public.appeal_cohort_review(gen_random_uuid(),'60000000-0000-4000-8000-000000005901','20000000-0000-4000-8000-000000004702',4,1,'Please verify the blank answer.');
reset role;
select is((select count(*)::int from public.push_targets(current_setting('test.outbox')::bigint)),0,'appeal suppresses unsent obsolete result notice');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004301","role":"authenticated","gina":{"admin":true}}',true);
select pg_temp.review(rev=>1,pts=>'{"c1":0,"c2":0,"c3":0,"c4":0}',outcome=>'not_answered',ap=>1,response=>'No submitted text or drawing was found.');
select pg_temp.publish('80000000-0000-4000-8000-000000006002');
reset role;
select is((select count(*)::int from public.push_outbox where kind='cohort_results'),2,'new publication creates new event after appeal');
select is((select count(*)::int from public.push_targets(current_setting('test.outbox')::bigint)),0,'old publication token targets remain empty');
select is((select count(*)::int from public.push_targets((select max(id) from public.push_outbox where kind='cohort_results'))),2,'new publication reaches both parents');
select is(gina.cohort_notification_current('{"group_id":"not-a-uuid","publication_version":"oops"}','10000000-0000-4000-8000-000000004302'),false,'malformed stored payload fails closed without cast exception');
select is(gina.cohort_notification_current('{"group_id":"60000000-0000-4000-8000-000000005901","publication_version":2}','10000000-0000-4000-8000-000000004303'),false,'foreign family cannot receive a cohort notice');
select lives_ok($$delete from public.families where id='10000000-0000-4000-8000-000000004302';set constraints all immediate;$$,'account deletion cleans result notification');
select is((select count(*)::int from public.push_outbox where kind='cohort_results'),0,'no retained family result notification');
select * from finish();rollback;
